/**
 * @brief Ultra-fast exp(x) approximation for x <= 0.0 using linear LUT interpolation
 * Typical execution time: ~3 CPU cycles (vs ~120 cycles for libc expf)
 */
static inline float fast_expf(float x) {
    if (x <= -16.0f) return 0.0f;
    if (x >= 0.0f) return 1.0f;
    
    // Domain [-16.0f, 0.0f] mapped to [0, 511]
    // index = (x + 16.0f) * (511.0f / 16.0f)
    float val = (x + 16.0f) * 31.9375f;
    uint32_t idx = (uint32_t)val;
    if (idx >= 511) return EXP_LUT[511];
    
    float frac = val - (float)idx;
    return EXP_LUT[idx] + frac * (EXP_LUT[idx + 1] - EXP_LUT[idx]);
}

/**
 * @brief Fast GELU activation using linear LUT interpolation in [-4.0, 4.0]
 */
static inline float fast_gelu(float x) {
    if (x <= -4.0f) return 0.0f;
    if (x >= 4.0f) return x;
    
    // Domain [-4.0f, 4.0f] mapped to [0, 511]
    // index = (x + 4.0f) * (511.0f / 8.0f)
    float val = (x + 4.0f) * 63.875f;
    uint32_t idx = (uint32_t)val;
    if (idx >= 511) return GELU_LUT[511];
    
    float frac = val - (float)idx;
    return GELU_LUT[idx] + frac * (GELU_LUT[idx + 1] - GELU_LUT[idx]);
}

/**
 * @brief Fast SiLU / Swish activation using linear LUT interpolation in [-8.0, 8.0]
 */
static inline float fast_silu(float x) {
    if (x <= -8.0f) return 0.0f;
    if (x >= 8.0f) return x;
    
    // Domain [-8.0f, 8.0f] mapped to [0, 511]
    // index = (x + 8.0f) * (511.0f / 16.0f)
    float val = (x + 8.0f) * 31.9375f;
    uint32_t idx = (uint32_t)val;
    if (idx >= 511) return SILU_LUT[511];
    
    float frac = val - (float)idx;
    return SILU_LUT[idx] + frac * (SILU_LUT[idx + 1] - SILU_LUT[idx]);
}

/**
 * @brief High-performance numerically stable Softmax using fast_expf LUT
 * @param vec Array of logits (in-place replacement with probabilities)
 * @param size Length of vector
 */
static inline void fast_softmax(float* vec, uint32_t size) {
    if (size == 0) return;
    
    // 1. Find maximum logit for numerical stability
    float max_v = vec[0];
    for (uint32_t i = 1; i < size; i++) {
        if (vec[i] > max_v) max_v = vec[i];
    }
    
    // 2. Subtract max and compute fast exp
    float sum_exp = 0.0f;
    for (uint32_t i = 0; i < size; i++) {
        float e = fast_expf(vec[i] - max_v);
        vec[i] = e;
        sum_exp += e;
    }
    
    // 3. Normalize probabilities
    float inv_sum = 1.0f / (sum_exp > 1e-7f ? sum_exp : 1.0f);
    for (uint32_t i = 0; i < size; i++) {
        vec[i] *= inv_sum;
    }
}

